// rsa_pkcs1_3072_test.json (group 0, tcIds 1, 2, 3; group 1, tcId 36),
// rsa_pkcs1_4096_test.json (group 0, tcIds 1, 2, 3; group 1, tcId 36). And
// changed: the JSON is rewritten as Nish source by generate.mjs beside this
// file; each key keeps its privateKeyPkcs8 as upstream wrote it, with the
// offsets of its RSAPrivateKey and its public key re-encoded as an RSAPublicKey
// by node; each case keeps its id, ciphertext and message, and the comments and
// flags are left out. The PSS signatures are not Wycheproof's: generate.mjs
// computes them and OpenSSL verifies each. `tests/link/crypto_rsa_sign` runs
// them. Generated: do not edit; run generate.mjs again.

/** A private key: its PKCS #8 DER in hex, where the PKCS #1 key starts and ends in it, and its RSAPublicKey DER in hex. */
export interface SignKey {
  bits: number;
  pkcs8: string;
  start: number;
  end: number;
  pub: string;
}

/** A Wycheproof decryption case: the ciphertext the private operation opens, and the message its PKCS #1 v1.5 block carries. */
export interface RawCase {
  key: number;
  tcId: number;
  ct: string;
  msg: string;
}

/** A PSS known answer: the message and its RSASSA-PSS-SHA256 signature under the derived salt. */
export interface PssCase {
  key: number;
  msg: string;
  sig: string;
}

/** The keys, 6 of them. */
export const signKeys = (): SignKey[] => [
  { bits: 2048, pkcs8: "", start: 26, end: 1217, pub: "" },
  { bits: 2048, pkcs8: "", start: 26, end: 1217, pub: "" },
  { bits: 3072, pkcs8: "", start: 26, end: 1793, pub: "" },
  { bits: 3072, pkcs8: "", start: 26, end: 1793, pub: "" },
  { bits: 4096, pkcs8: "", start: 26, end: 2375, pub: "" },
  { bits: 4096, pkcs8: "", start: 26, end: 2376, pub: "" },
];

